const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const raw = String(execution.error?.message ?? 'workflow failed');
const safe = raw.replace(/(?:Bearer\s+)?[A-Za-z0-9_-]{20,}/g, '[REDACTED]').slice(0, 500);
return [{ json: { workflow: workflow.name ?? 'unknown', node_name: execution.lastNodeExecuted ?? null, error_code: execution.error?.name ?? 'WORKFLOW_ERROR', retryable: /timeout|429|5\d\d/i.test(raw), retry_count: 0, payload_safe: { message: safe }, correlation_id: execution.id ?? null } }];
